import React, { useEffect, useState } from "react";
import axios from "axios";
import { useNavigate } from "react-router-dom";

const Reports = () => {
  const [users, setUsers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const navigate = useNavigate();

  useEffect(() => {
    const fetchUsers = async () => {
      try {
        const token = localStorage.getItem("token");
        const response = await axios.get("http://localhost:5001/api/reports/users", {
          headers: { Authorization: `Bearer ${token}` }
        });
        
        console.log("API Response:", response.data);
        
        if (response.data && Array.isArray(response.data)) {
          setUsers(response.data);
        } else {
          throw new Error("Invalid data format received");
        }
      } catch (error) {
        console.error("Error fetching users:", error);
        setError(error.response?.data?.error || error.message || "Failed to fetch users");
        if (error.response?.status === 401) {
          navigate("/login");
        }
      } finally {
        setLoading(false);
      }
    };

    fetchUsers();
  }, [navigate]);

  if (loading) return <div className="loading">Loading user data...</div>;
  if (error) return <div className="error">Error: {error}</div>;

  return (
    <div className="reports-container">
      <h2>User Reports</h2>
      <button onClick={() => navigate(-1)} className="back-button">
        Back to Dashboard
      </button>
      
      {users.length > 0 ? (
        <table className="users-table">
          <thead>
            <tr>
              <th>ID</th>
              <th>Name</th>
              <th>Email</th>
              <th>Role</th>
              <th>PTO Balance</th>
              <th>Sick Leave</th>
            </tr>
          </thead>
          <tbody>
            {users.map(user => (
              <tr key={user.id}>
                <td>{user.id}</td>
                <td>{user.name || 'N/A'}</td>
                <td>{user.email || 'N/A'}</td>
                <td>{user.role || 'N/A'}</td>
                <td>{user.ptoBalance || 0}</td>
                <td>{user.sickLeaveBalance || 0}</td>
              </tr>
            ))}
          </tbody>
        </table>
      ) : (
        <p>No user data available</p>
      )}
    </div>
  );
};

export default Reports;
